res = env.run(["find", "src", "-type", "f"], check = False)
listing = res.stdout

# Perform the rename in files under src/ only
edits = {}
for path in ["src/a.txt", "src/nested/b.txt"]:
    before = repo.read(path)
    repo.edit(path, "slow_path", "fast_path", all = True)
    edits[path] = {"before": before, "after": repo.read(path)}

result = {"find_listing": listing, "edits": edits, "status": repo.status()}
return result
